from pathlib import Path


def replace_once(path: str, old: str, new: str, label: str) -> None:
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected one match in {path}, found {count}")
    p.write_text(text.replace(old, new, 1), encoding="utf-8")


store_path = "drive/scripts/research_data_mcp/discover_intent_store.py"

replace_once(
    store_path,
    '''    def create(\n''',
    '''    def _get_locked(self, db: sqlite3.Connection, intent_id: str) -> dict[str, Any]:\n        db.row_factory = sqlite3.Row\n        row = db.execute("SELECT * FROM discover_intents WHERE id = ?", (intent_id,)).fetchone()\n        if not row:\n            raise KeyError(intent_id)\n        item = dict(row)\n        require_owner(item.get("owner_id"), intent_id)\n        item["state"] = json.loads(item.pop("state_json") or "{}")\n        return item\n\n    def _save_locked(self, db: sqlite3.Connection, intent_id: str, state: dict[str, Any]) -> None:\n        db.execute(\n            "UPDATE discover_intents SET updated_at=?, state_json=? WHERE id=?",\n            (_now(), json.dumps(_clone(state)), intent_id),\n        )\n\n    def _event_locked(\n        self,\n        db: sqlite3.Connection,\n        intent_id: str,\n        kind: str,\n        payload: dict[str, Any],\n    ) -> None:\n        db.execute(\n            "INSERT INTO discover_intent_events(intent_id, created_at, kind, payload_json) "\n            "VALUES (?, ?, ?, ?)",\n            (intent_id, _now(), kind[:80], json.dumps(payload)),\n        )\n\n    @staticmethod\n    def _collection_started(state: dict[str, Any]) -> bool:\n        collection = dict(state.get("collection") or {})\n        status = str(collection.get("status") or "not_started").strip() or "not_started"\n        return bool(collection.get("job_id")) or status not in {"not_started"}\n\n    def create(\n''',
    "add transactional helpers",
)

replace_once(
    store_path,
    '''    def get(self, intent_id: str) -> dict[str, Any]:\n        with self._db() as db:\n            db.row_factory = sqlite3.Row\n            row = db.execute("SELECT * FROM discover_intents WHERE id = ?", (intent_id,)).fetchone()\n        if not row:\n            raise KeyError(intent_id)\n        item = dict(row)\n        require_owner(item.get("owner_id"), intent_id)\n        item["state"] = json.loads(item.pop("state_json") or "{}")\n        return item\n''',
    '''    def get(self, intent_id: str) -> dict[str, Any]:\n        with self._db() as db:\n            return self._get_locked(db, intent_id)\n''',
    "reuse locked row decoder",
)

replace_once(
    store_path,
    '''    def _event(self, intent_id: str, kind: str, payload: dict[str, Any]) -> None:\n        with self._db() as db:\n            db.execute(\n                "INSERT INTO discover_intent_events(intent_id, created_at, kind, payload_json) VALUES (?, ?, ?, ?)",\n                (intent_id, _now(), kind[:80], json.dumps(payload)),\n            )\n''',
    '''    def _event(self, intent_id: str, kind: str, payload: dict[str, Any]) -> None:\n        with self._db() as db:\n            self._event_locked(db, intent_id, kind, payload)\n''',
    "reuse transactional event writer",
)

start = Path(store_path).read_text(encoding="utf-8")
old_start = start.index("    def set_proposal(")
old_end = start.index("    def events(", old_start)
old_block = start[old_start:old_end]
new_block = '''    def set_proposal(self, intent_id: str, proposal: dict[str, Any]) -> dict[str, Any]:\n        validated = validate_proposal(proposal)\n        with self._db() as db:\n            db.execute("BEGIN IMMEDIATE")\n            current = self._get_locked(db, intent_id)\n            state = _clone(current["state"])\n            if self._collection_started(state):\n                raise ValueError("cannot replace proposal after collection submission has started")\n            # A new proposal supersedes every previously reviewed route. Leaving\n            # old routes executable while a replacement is pending lets stale\n            # evidence advice cross a consequential authority boundary.\n            state["proposal"] = validated\n            state["routes"] = []\n            state["selected_route_id"] = ""\n            state["status"] = "proposal_ready"\n            self._save_locked(db, intent_id, state)\n            self._event_locked(db, intent_id, "proposal", {"proposal": state["proposal"]})\n        return self.get(intent_id)\n\n    def review_proposal(\n        self,\n        intent_id: str,\n        *,\n        decision: str,\n        proposal_id: str,\n        proposal_hash: str,\n    ) -> dict[str, Any]:\n        with self._db() as db:\n            db.execute("BEGIN IMMEDIATE")\n            current = self._get_locked(db, intent_id)\n            state = _clone(current["state"])\n            if self._collection_started(state):\n                raise ValueError("cannot review proposal after collection submission has started")\n            if state.get("status") != "proposal_ready":\n                raise ValueError("Discover proposal is not ready for review")\n            proposal = state.get("proposal") or {}\n            if proposal_id != proposal.get("id") or proposal_hash != proposal.get("proposal_hash"):\n                raise ValueError("Discover proposal changed; refresh before reviewing")\n            normalized = str(decision or "").strip().lower()\n            if normalized == "accept":\n                state["routes"] = proposal.get("routes") or []\n                state["selected_route_id"] = (\n                    proposal.get("recommended_route_id") or state["routes"][0]["id"]\n                )\n                state["proposal"] = None\n                state["status"] = "ready_for_review"\n            elif normalized == "reject":\n                state["proposal"] = None\n                state["routes"] = []\n                state["selected_route_id"] = ""\n                state["status"] = "draft"\n            else:\n                raise ValueError("decision must be accept or reject")\n            self._save_locked(db, intent_id, state)\n            self._event_locked(\n                db,\n                intent_id,\n                normalized,\n                {"proposal_id": proposal_id, "proposal_hash": proposal_hash},\n            )\n        return self.get(intent_id)\n\n    def select_route(self, intent_id: str, route_id: str) -> dict[str, Any]:\n        with self._db() as db:\n            db.execute("BEGIN IMMEDIATE")\n            current = self._get_locked(db, intent_id)\n            state = _clone(current["state"])\n            if state.get("status") != "ready_for_review":\n                raise ValueError("route selection requires a reviewed Discover proposal")\n            if self._collection_started(state):\n                raise ValueError("cannot change route after collection submission has started")\n            ids = {row.get("id") for row in state.get("routes") or []}\n            if route_id not in ids:\n                raise ValueError("route_id is not part of this Discover intent")\n            state["selected_route_id"] = route_id\n            self._save_locked(db, intent_id, state)\n            self._event_locked(db, intent_id, "route_selected", {"route_id": route_id})\n        return self.get(intent_id)\n\n    def reserve_submission(self, intent_id: str) -> dict[str, Any]:\n        """Atomically freeze the reviewed route before a queue side effect.\n\n        A retry of the same in-flight reservation is safe: the deterministic\n        queue id will deduplicate job creation and `link_job` will finalize it.\n        """\n        with self._db() as db:\n            db.execute("BEGIN IMMEDIATE")\n            current = self._get_locked(db, intent_id)\n            state = _clone(current["state"])\n            collection = dict(state.get("collection") or {})\n            status = str(collection.get("status") or "not_started")\n\n            if state.get("status") == "submitting" and status == "submitting":\n                route_id = str(collection.get("route_id") or "")\n                if not route_id or route_id != str(state.get("selected_route_id") or ""):\n                    raise ValueError("Discover submission reservation is inconsistent")\n                return current\n\n            if state.get("status") != "ready_for_review":\n                raise ValueError("Discover intent must be reviewed and ready before submission")\n            if self._collection_started(state):\n                raise ValueError("Discover collection submission has already started")\n            selected = str(state.get("selected_route_id") or "")\n            route = next(\n                (row for row in state.get("routes") or [] if str(row.get("id") or "") == selected),\n                None,\n            )\n            if not selected or not route:\n                raise ValueError("select a reviewed acquisition route before collection")\n\n            collection.update({\n                "job_id": "",\n                "status": "submitting",\n                "route_id": selected,\n                "registered_dataset_id": str(collection.get("registered_dataset_id") or ""),\n            })\n            state["collection"] = collection\n            state["status"] = "submitting"\n            self._save_locked(db, intent_id, state)\n            self._event_locked(db, intent_id, "submission_reserved", {"route_id": selected})\n        return self.get(intent_id)\n\n    def abort_submission(self, intent_id: str, *, reason: str = "") -> dict[str, Any]:\n        """Release an in-flight reservation only when no job has been linked."""\n        with self._db() as db:\n            db.execute("BEGIN IMMEDIATE")\n            current = self._get_locked(db, intent_id)\n            state = _clone(current["state"])\n            collection = dict(state.get("collection") or {})\n            if collection.get("job_id"):\n                return current\n            if state.get("status") != "submitting" or collection.get("status") != "submitting":\n                return current\n            collection["status"] = "not_started"\n            collection["route_id"] = ""\n            state["collection"] = collection\n            state["status"] = "ready_for_review"\n            self._save_locked(db, intent_id, state)\n            self._event_locked(\n                db,\n                intent_id,\n                "submission_aborted",\n                {"reason": str(reason or "")[:240]},\n            )\n        return self.get(intent_id)\n\n    def link_job(self, intent_id: str, job: dict[str, Any]) -> dict[str, Any]:\n        job_id = str(job.get("id") or "").strip()\n        if not job_id:\n            raise ValueError("collection job id is required")\n        with self._db() as db:\n            db.execute("BEGIN IMMEDIATE")\n            current = self._get_locked(db, intent_id)\n            state = _clone(current["state"])\n            collection = dict(state.get("collection") or {})\n            existing_job_id = str(collection.get("job_id") or "").strip()\n            if existing_job_id:\n                if existing_job_id == job_id:\n                    return current\n                raise ValueError("Discover intent already has a different collection job")\n            route_id = str(collection.get("route_id") or state.get("selected_route_id") or "")\n            collection.update({\n                "job_id": job_id,\n                "status": str(job.get("status") or "pending_approval"),\n                "route_id": route_id,\n            })\n            state["collection"] = collection\n            state["status"] = "pending_approval"\n            self._save_locked(db, intent_id, state)\n            self._event_locked(\n                db,\n                intent_id,\n                "job_linked",\n                {"job_id": job_id, "route_id": route_id},\n            )\n        return self.get(intent_id)\n\n'''
Path(store_path).write_text(start[:old_start] + new_block + start[old_end:], encoding="utf-8")

# Gateway: reserve the selected route before any plan resolution / queue side effect,
# abort only when no job was created, and let a linked-orphan retry reconcile via
# the deterministic queue id.
gateway_path = "drive/scripts/research_data_mcp/gateway.py"
gateway = Path(gateway_path).read_text(encoding="utf-8")
old_start = gateway.index("    def discover_intent_submit_collection(")
old_end = gateway.index("    # --- Discover Explore: sources, preview, refresh subscriptions, history ---", old_start)
old_gateway = gateway[old_start:old_end]
new_gateway = '''    def discover_intent_submit_collection(self, intent_id: str, *, limit: int = 200) -> dict:\n        store = self._discover_intent_store()\n        intent = store.reserve_submission(intent_id)\n        state = intent.get("state") or {}\n        collection = state.get("collection") or {}\n        selected_id = str(collection.get("route_id") or state.get("selected_route_id") or "")\n        route = next((row for row in state.get("routes") or [] if row.get("id") == selected_id), None)\n        if not route:\n            store.abort_submission(intent_id, reason="reserved route is unavailable")\n            raise ValueError("select a reviewed acquisition route before collection")\n\n        try:\n            crafted = route.get("collect_plan") if isinstance(route.get("collect_plan"), dict) else None\n            if crafted:\n                from scripts.research_data_mcp.craft_collect import validate_generic_plan\n\n                plan = dict(validate_generic_plan(crafted))\n                plan.update(\n                    {\n                        "discover_intent_id": intent_id,\n                        "candidate_key": route.get("candidate_key")\n                        or (state.get("candidate") or {}).get("candidate_key")\n                        or "",\n                        "destination": route.get("destination") or plan.get("destination") or "",\n                        "refresh_strategy": route.get("refresh") or "",\n                    }\n                )\n                submitted = self.jobs.submit(\n                    plan.get("title") or intent.get("title") or "Discover crafted collect",\n                    plan,\n                    {\n                        "source": "discover_intent",\n                        "discover_intent_id": intent_id,\n                        "idempotency_key": f"discover:{intent_id}",\n                        "research_need": intent.get("research_need") or "",\n                        "route_id": selected_id,\n                        "crafted": True,\n                        "pipeline": "custom",\n                    },\n                    auto_approve=False,\n                )\n                job = submitted.get("job") or {}\n                if not job:\n                    raise ValueError(str(submitted.get("error") or "Discover collection plan is not launchable"))\n                linked = store.link_job(intent_id, job)\n                return {\n                    "intent": self._discover_intent_with_job(linked),\n                    "job": job,\n                    "crafted": True,\n                }\n\n            connector_id = str(route.get("connector_id") or "")\n            if not connector_id:\n                raise ValueError(\n                    "selected route needs either an AI-crafted collect_plan or a verified connector_id"\n                )\n            from scripts.research_data_mcp.discover_collect_plan import resolve_discover_collect_plan\n\n            plan = dict(\n                resolve_discover_collect_plan(\n                    self.procurement,\n                    self.repo_root,\n                    connector_id=connector_id,\n                    source_id=str(\n                        (state.get("candidate") or {}).get("source_id")\n                        or intent.get("source_id")\n                        or ""\n                    ),\n                    limit=min(max(int(limit), 1), 2000),\n                    title=str(intent.get("title") or ""),\n                    url=str(route.get("url") or route.get("source_url") or ""),\n                    candidate_key=str(\n                        route.get("candidate_key")\n                        or (state.get("candidate") or {}).get("candidate_key")\n                        or ""\n                    ),\n                    doi=str(route.get("doi") or (state.get("candidate") or {}).get("doi") or ""),\n                    external_id=str(\n                        route.get("external_id")\n                        or (state.get("candidate") or {}).get("external_id")\n                        or ""\n                    ),\n                    provider=str(\n                        route.get("provider")\n                        or (state.get("candidate") or {}).get("provider")\n                        or ""\n                    ),\n                    kind=str(route.get("kind") or (state.get("candidate") or {}).get("kind") or ""),\n                    dataset_id=str(\n                        route.get("dataset_id")\n                        or (state.get("candidate") or {}).get("dataset_id")\n                        or ""\n                    ),\n                )\n            )\n            plan.update(\n                {\n                    "discover_intent_id": intent_id,\n                    "candidate_key": route.get("candidate_key")\n                    or (state.get("candidate") or {}).get("candidate_key")\n                    or "",\n                    "destination": route.get("destination") or plan.get("destination") or "",\n                    "refresh_strategy": route.get("refresh") or "",\n                }\n            )\n            submitted = self.jobs.submit(\n                plan.get("title") or intent.get("title") or "Discover collection",\n                plan,\n                {\n                    "source": "discover_intent",\n                    "discover_intent_id": intent_id,\n                    "idempotency_key": f"discover:{intent_id}",\n                    "research_need": intent.get("research_need") or "",\n                    "route_id": selected_id,\n                    "connector_id": connector_id,\n                },\n                auto_approve=False,\n            )\n            job = submitted.get("job") or {}\n            if not job:\n                raise ValueError(str(submitted.get("error") or "Discover collection plan is not launchable"))\n        except Exception as exc:\n            # Before a job exists, rollback the reservation so the researcher can\n            # correct or retry. If the deterministic queue call succeeded,\n            # `link_job` below is the only remaining transition and a retry can\n            # recover the same job id without creating another consequence.\n            store.abort_submission(intent_id, reason=str(exc))\n            raise\n\n        linked = store.link_job(intent_id, job)\n        return {"intent": self._discover_intent_with_job(linked), "job": job}\n\n'''
Path(gateway_path).write_text(gateway[:old_start] + new_gateway + gateway[old_end:], encoding="utf-8")

print("Applied transactional Discover intent authority hardening")
